import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.B-PsUuVJ.js";const p=JSON.parse('{"title":"HMR 相关问题","description":"","frontmatter":{},"headers":[],"relativePath":"ray-template-docs/common-problem/hmr.md","filePath":"ray-template-docs/common-problem/hmr.md","lastUpdated":1788226951000}'),c={name:"ray-template-docs/common-problem/hmr.md"};function d(s,e,u,n,l,i){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="hmr-相关问题" tabindex="-1">HMR 相关问题 <a class="header-anchor" href="#hmr-相关问题" aria-label="Permalink to &quot;HMR 相关问题&quot;">​</a></h1><p>模板使用 <code>vite</code> 做为构建工具，<code>vite</code> 默认支持 HMR（热模块替换）。</p><h2 id="usevuerouter-usei18n-导致报错" tabindex="-1">useVueRouter, useI18n 导致报错 <a class="header-anchor" href="#usevuerouter-usei18n-导致报错" aria-label="Permalink to &quot;useVueRouter, useI18n 导致报错&quot;">​</a></h2><h3 id="在顶层更新代码导致报错" tabindex="-1">在顶层更新代码导致报错 <a class="header-anchor" href="#在顶层更新代码导致报错" aria-label="Permalink to &quot;在顶层更新代码导致报错&quot;">​</a></h3><p>例如，在 <code>Layout.tsx</code> 中更新了代码，页面可能就会因为使用了 <code>useVueRouter</code>, <code>useI18n</code> 等 hook 导致报错。</p><p>因为，在模板中为了满足一些业务需求，需要异步注册 <code>vue-router</code> 和 <code>vue-i18n</code>，所以在顶层更新代码时，可能会导致报错。</p><p>目前还没有好的解决方案，可以通过手动刷新页面来解决。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>在 <code>v4.7.0</code> 版本中，修复了 <code>useVueRouter</code> 的问题，但是 <code>useI18n</code> 还是可能会报错。</p></div>',8)])])}const h=o(c,[["render",d]]);export{p as __pageData,h as default};
